<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class Campaign extends Model {protected $fillable=['name','channel','objective','target_audience','start_date','end_date','budget','status','notes'];protected function casts():array{return ['start_date'=>'date','end_date'=>'date','budget'=>'decimal:2'];}public function leads(){return $this->hasMany(Lead::class);}}